-- Source: FBI NICS Firearm Background Checks (Data Liberation Project CSV mirror) (16445 rows)
-- Generated by gen_mart_models.py

with source as (
    select * from {{ source('ripple_raw', 'FED_FBI_NICS_CHECKS') }}
)

select
    "MONTH" as month,
    STATE as state,
    PERMIT as permit,
    PERMIT_RECHECK as permit_recheck,
    HANDGUN as handgun,
    try_to_double(LONG_GUN) as long_gun,
    OTHER as other,
    MULTIPLE as multiple,
    ADMIN as admin,
    PREPAWN_HANDGUN as prepawn_handgun,
    try_to_double(PREPAWN_LONG_GUN) as prepawn_long_gun,
    PREPAWN_OTHER as prepawn_other,
    REDEMPTION_HANDGUN as redemption_handgun,
    try_to_double(REDEMPTION_LONG_GUN) as redemption_long_gun,
    REDEMPTION_OTHER as redemption_other,
    RETURNED_HANDGUN as returned_handgun,
    try_to_double(RETURNED_LONG_GUN) as returned_long_gun,
    RETURNED_OTHER as returned_other,
    RENTALS_HANDGUN as rentals_handgun,
    try_to_double(RENTALS_LONG_GUN) as rentals_long_gun,
    PRIVATE_SALE_HANDGUN as private_sale_handgun,
    try_to_double(PRIVATE_SALE_LONG_GUN) as private_sale_long_gun,
    PRIVATE_SALE_OTHER as private_sale_other,
    RETURN_TO_SELLER_HANDGUN as return_to_seller_handgun,
    try_to_double(RETURN_TO_SELLER_LONG_GUN) as return_to_seller_long_gun,
    RETURN_TO_SELLER_OTHER as return_to_seller_other,
    try_to_double(TOTALS) as totals
from source
